/* From Uiverse.io by Pranali9922  - Tags: card, cool card, card animation, card hover */
.__UIV_SCOPE__ .card {
  width: 200px;
  height: 200px;
  transition: all 0.2s;
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .card-inner {
  width: inherit;
  height: inherit;
  background: rgba(255, 255, 255, 0.05);
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.25);
  backdrop-filter: blur(10px);
  border-radius: 8px;
}

.__UIV_SCOPE__ .card:hover {
  transform: scale(1.04) rotate(1deg);
}

.__UIV_SCOPE__ .circle {
  width: 100px;
  height: 100px;
  background: repeating-linear-gradient(48deg, #3023ae 0%, #ff0099 100%);
  border-radius: 35% 30% 75% 30% / 49% 30% 70% 51%;
  position: absolute;
  animation: move-up6 2s ease-in infinite alternate-reverse;
}

.__UIV_SCOPE__ .circle:nth-child(1) {
  top: -25px;
  left: -25px;
}

.__UIV_SCOPE__ .circle:nth-child(2) {
  bottom: -25px;
  right: -25px;
  animation-name: move-down1;
}

@keyframes move-up6 {
  to {
    transform: translateY(-10px);
  }
}

@keyframes move-down1 {
  to {
    transform: translateY(10px);
  }
}
